#include "xparameters.h"
#include "xil_io.h"
#include "xil_cache.h"
#include "xaxidma.h"
#include <stdint.h>
#include <stdio.h>

/*
 * Replace these addresses/IDs with values generated by your Vivado/Vitis design.
 * This example deliberately uses generated XPAR symbols where available.
 */
/* The block-design instance is `npu_0` (module npu_bd_top, interface
 * S_AXI_CTRL). Vitis names the base address macro after that instance; the
 * exact spelling depends on the tool version, so probe the known forms and
 * fall back to defining NPU_CTRL_BASE=0x43C00000 yourself. */
#ifndef NPU_CTRL_BASE
#  if defined(XPAR_NPU_0_S_AXI_CTRL_BASEADDR)
#    define NPU_CTRL_BASE XPAR_NPU_0_S_AXI_CTRL_BASEADDR
#  elif defined(XPAR_NPU_0_BASEADDR)
#    define NPU_CTRL_BASE XPAR_NPU_0_BASEADDR
#  elif defined(XPAR_NPU_AXIS_SYSTEM_TOP_0_S_AXI_BASEADDR)
#    define NPU_CTRL_BASE XPAR_NPU_AXIS_SYSTEM_TOP_0_S_AXI_BASEADDR
#  else
#    error "NPU base address macro not found: check xparameters.h or -DNPU_CTRL_BASE=0x43C00000"
#  endif
#endif

#define REG_CTRL   0x00
#define REG_M      0x04
#define REG_N      0x08
#define REG_K      0x0C
#define REG_ACT    0x10
#define REG_CMD    0x14
#define REG_QMUL   0x18
#define REG_QSHIFT 0x1C
#define REG_ZP     0x20
#define REG_VERSION 0x24
#define REG_CAPS    0x28
#define REG_LASTJOB 0x3C

static inline void npu_wr(uint32_t off, uint32_t v) {
    Xil_Out32(NPU_CTRL_BASE + off, v);
}
static inline uint32_t npu_rd(uint32_t off) {
    return Xil_In32(NPU_CTRL_BASE + off);
}

#ifndef NPU_POLL_LIMIT
#define NPU_POLL_LIMIT 100000000u
#endif

/* A failure cancels both DMA directions; an outstanding RX must not survive. */
static int npu_cancel_dma(XAxiDma *dma, int status) {
    npu_wr(REG_CMD, 1u<<4);
    XAxiDma_Reset(dma);
    for (uint32_t n=0; n<NPU_POLL_LIMIT; ++n)
        if (XAxiDma_ResetIsDone(dma)) return status;
    return -6; /* DMA reset failed: caller must recover hardware before reuse */
}

static int npu_wait_done(void) {
    for (uint32_t timeout=0; timeout<NPU_POLL_LIMIT; ++timeout) {
        uint32_t s=npu_rd(REG_CTRL);
        if (s & (1u<<2)) return -2; /* config error */
        if (s & (1u<<1)) return 0;  /* sticky done */
    }
    npu_wr(REG_CMD, 1u<<4); /* abort stalled datapath */
    return -1;
}

/*
 * The AXI output stream emits one 32-bit word per result element.  The low
 * byte is the postprocessed signed INT8 value (sign-extended to 32 bits).
 * For matrices larger than one 8x8 tile the DMA buffer is tile-major, not
 * conventional global row-major.  Use unpack_matmul_rowmajor_i8() below
 * before consuming it as a normal MxN tensor.
 */
int run_matmul(XAxiDma *dma,
               uint8_t *feed, uint32_t feed_bytes,
               uint32_t *result_words, uint32_t result_bytes,
               uint16_t M, uint16_t N, uint16_t K)
{
    uint64_t expected_feed = ((uint64_t)M+7u)/8u * (((uint64_t)N+7u)/8u) * ((uint64_t)K+7u)*16u;
    if (!dma || !feed || !result_words || !M || !N || !K ||
        expected_feed != feed_bytes || (uint64_t)M*N*4u != result_bytes) return -7;
    if ((npu_rd(REG_CTRL) & 1u) ||
        XAxiDma_Busy(dma, XAXIDMA_DMA_TO_DEVICE) ||
        XAxiDma_Busy(dma, XAXIDMA_DEVICE_TO_DMA)) return -8;

    npu_wr(REG_M, M);
    npu_wr(REG_N, N);
    npu_wr(REG_K, K);
    npu_wr(REG_ACT, 1);      /* ReLU on; use 0 if not wanted */
    npu_wr(REG_QMUL, 1);
    npu_wr(REG_QSHIFT, 0);
    npu_wr(REG_ZP, 0);

    Xil_DCacheFlushRange((UINTPTR)feed, feed_bytes);
    Xil_DCacheFlushRange((UINTPTR)result_words, result_bytes);

    int st=XAxiDma_SimpleTransfer(dma,(UINTPTR)result_words,result_bytes,XAXIDMA_DEVICE_TO_DMA);
    if(st!=XST_SUCCESS) return npu_cancel_dma(dma, -3);
    st=XAxiDma_SimpleTransfer(dma,(UINTPTR)feed,feed_bytes,XAXIDMA_DMA_TO_DEVICE);
    if(st!=XST_SUCCESS) return npu_cancel_dma(dma, -4);

    npu_wr(REG_CTRL, 1u); /* mode=0, START=1 */

    st=npu_wait_done();
    if (st) return npu_cancel_dma(dma, st);
    uint32_t polls;
    for (polls=0; polls<NPU_POLL_LIMIT; ++polls) {
        if (!XAxiDma_Busy(dma, XAXIDMA_DMA_TO_DEVICE) &&
            !XAxiDma_Busy(dma, XAXIDMA_DEVICE_TO_DMA)) break;
    }
    if (polls == NPU_POLL_LIMIT) return npu_cancel_dma(dma, -5);
    Xil_DCacheInvalidateRange((UINTPTR)result_words,result_bytes);
    return st;
}

/* Convert compact tile-major DMA words into conventional row-major INT8. */
void unpack_matmul_rowmajor_i8(int8_t *dst, const uint32_t *src,
                               uint16_t M, uint16_t N)
{
    const uint16_t tile = 8;
    uint32_t si = 0;
    for (uint16_t tm = 0; tm < (uint16_t)((M + tile - 1u) / tile); ++tm) {
        for (uint16_t tn = 0; tn < (uint16_t)((N + tile - 1u) / tile); ++tn) {
            for (uint16_t r = 0; r < tile; ++r) {
                uint16_t gr = (uint16_t)(tm * tile + r);
                if (gr >= M) continue;
                for (uint16_t c = 0; c < tile; ++c) {
                    uint16_t gc = (uint16_t)(tn * tile + c);
                    if (gc >= N) continue;
                    dst[(uint32_t)gr * N + gc] = (int8_t)(src[si++] & 0xffu);
                }
            }
        }
    }
}
